'use client';

import type { DronePartId, DroneStage } from './types';

const PARTICLES = Array.from({ length: 64 }, (_, index) => {
  const angle = index * 2.399;
  const radius = 18 + ((index * 37) % 120);
  return {
    x: Math.round((250 + Math.cos(angle) * radius * 1.25) * 1000) / 1000,
    y: Math.round((160 + Math.sin(angle) * radius * 0.7) * 1000) / 1000,
    size: Math.round((0.7 + (index % 4) * 0.3) * 1000) / 1000,
  };
});

export function DroneSvgFallback({ state = 'activate', activePart = null }: {
  state?: DroneStage;
  activePart?: DronePartId | null;
}) {
  return (
    <svg className="drone-svg" viewBox="0 0 500 330" role="img" aria-labelledby="drone-fallback-title drone-fallback-description" data-state={state}>
      <title id="drone-fallback-title">KAALKRIT autonomous drone system diagram</title>
      <desc id="drone-fallback-description">A geometric quadcopter with a central intelligence metaphor, mechanical arms, electronics, sensors, and payload components.</desc>
      <g className="drone-svg__cloud" aria-hidden="true">
        {PARTICLES.map((particle, index) => <circle key={index} cx={particle.x} cy={particle.y} r={particle.size} fill={index % 5 === 0 ? '#8b5cf6' : index % 3 === 0 ? '#06b6d4' : '#c4c7c7'} />)}
      </g>
      <g className="drone-svg__grid" aria-hidden="true">
        <path d="M48 274H452M78 267V281M138 267V281M198 267V281M258 267V281M318 267V281M378 267V281M438 267V281" />
        <circle cx="250" cy="164" r="112" />
      </g>
      <g className="drone-svg__connectors" aria-hidden="true">
        <path d="M250 164L142 94M250 164L358 94M250 164L145 236M250 164L355 236M250 164L250 128M250 164L310 216" />
      </g>
      <g className="drone-svg__assembly">
        <g className="drone-svg__part drone-svg__part--rotor">
          <path className="drone-svg__arm" d="M220 151L142 94M280 151L358 94M220 179L145 236M280 179L355 236" />
          {[[142, 94], [358, 94], [145, 236], [355, 236]].map(([cx, cy]) => (
            <g key={String(cx) + '-' + String(cy)} className="drone-svg__rotor">
              <circle cx={cx ?? 0} cy={cy ?? 0} r="24" />
              <path d={'M' + ((cx ?? 0) - 12) + ' ' + ((cy ?? 0) - 3) + 'h24M' + ((cx ?? 0) - 12) + ' ' + ((cy ?? 0) + 3) + 'h24'} />
            </g>
          ))}
        </g>
        <g className={['drone-svg__part', 'drone-svg__part--airframe', activePart === 'airframe' ? 'is-active' : ''].join(' ')}>
          <path className="drone-svg__body" d="M207 143L250 117L293 143V192L250 218L207 192Z" />
          <path className="drone-svg__body-detail" d="M222 151L250 134L278 151M222 185L250 202L278 185" />
        </g>
        <g className={['drone-svg__part', 'drone-svg__part--electronics', activePart === 'electronics' ? 'is-active' : ''].join(' ')}>
          <rect x="230" y="153" width="40" height="28" />
          <path d="M236 160h28M236 168h18M236 176h24" />
        </g>
        <g className={['drone-svg__part', 'drone-svg__part--flight-controller', activePart === 'flight-controller' ? 'is-active' : ''].join(' ')}>
          <rect x="241" y="126" width="18" height="16" />
          <circle cx="250" cy="134" r="3" />
        </g>
        <g className="drone-svg__intelligence-core" aria-hidden="true">
          <circle cx="250" cy="134" r="15" />
          <circle cx="250" cy="134" r="5" />
          <path d="M235 134h30M250 119v30" />
        </g>
        <g className={['drone-svg__part', 'drone-svg__part--sensor', activePart === 'sensor' ? 'is-active' : ''].join(' ')}>
          <circle cx="358" cy="94" r="10" />
          <circle cx="358" cy="94" r="4" />
        </g>
        <g className={['drone-svg__part', 'drone-svg__part--payload', activePart === 'payload' ? 'is-active' : ''].join(' ')}>
          <path d="M288 191L330 207L322 226L280 210Z" />
          <circle cx="309" cy="212" r="7" />
        </g>
        <g className={['drone-svg__part', 'drone-svg__part--navigation', activePart === 'navigation' ? 'is-active' : ''].join(' ')}>
          <path d="M151 214l20-10 14 15-20 11z" />
          <path d="M161 215l9 5" />
        </g>
      </g>
      <text className="drone-svg__caption" x="48" y="304">DISTRIBUTED INTELLIGENCE / AUTONOMOUS SYSTEM</text>
      <text className="drone-svg__state" x="452" y="304" textAnchor="end">{state === 'activate' ? 'SYSTEM READY' : 'SYSTEM ' + state.toUpperCase()}</text>
    </svg>
  );
}
