'use client';

import { useGSAP } from '@gsap/react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { useRef, type RefObject } from 'react';
import type { DeploymentProgress, DroneStage } from './types';

gsap.registerPlugin(useGSAP, ScrollTrigger);

const DEPLOYMENT_TRIGGER_ID = 'kaalkrit-drone-deployment';

type UseDroneDeploymentOptions = {
  scope: RefObject<HTMLDivElement | null>;
  pinTarget: RefObject<HTMLDivElement | null>;
  progress: DeploymentProgress;
  sceneReady: boolean;
  onStageChange: (stage: DroneStage) => void;
};

export function useDroneDeployment({ scope, pinTarget, progress, sceneReady, onStageChange }: UseDroneDeploymentOptions) {
  const timelineRef = useRef<gsap.core.Timeline | null>(null);
  const stageRef = useRef<DroneStage>('dormant');

  useGSAP(() => {
    if (!scope.current || !pinTarget.current || !sceneReady) return;

    const media = gsap.matchMedia();
    media.add(
      {
        desktop: '(min-width: 48rem)',
        mobile: '(max-width: 47.99rem)',
        reduced: '(prefers-reduced-motion: reduce)',
      },
      (context) => {
        if (context.conditions?.mobile || context.conditions?.reduced) return undefined;

        const timeline = gsap.timeline({
          paused: true,
          defaults: { ease: 'none' },
          onUpdate: () => {
            const nextProgress = timeline.progress();
            progress.value = nextProgress;
            const nextStage = nextProgress < 0.15
              ? 'dormant'
              : nextProgress < 0.3
                ? 'awaken'
                : nextProgress < 0.6
                  ? 'unfold'
                  : nextProgress < 0.8
                    ? 'deploy'
                    : 'activate';
            if (stageRef.current !== nextStage) {
              stageRef.current = nextStage;
              onStageChange(nextStage);
            }
          },
        });

        timeline.to(progress, { value: 1, duration: 1 });
        timelineRef.current = timeline;

        ScrollTrigger.create({
          id: DEPLOYMENT_TRIGGER_ID,
          trigger: scope.current,
          start: 'top top',
          end: () => `+=${Math.max(window.innerHeight, 720)}`,
          pin: pinTarget.current,
          pinSpacing: false,
          scrub: 1,
          animation: timeline,
          invalidateOnRefresh: true,
        });

        requestAnimationFrame(() => ScrollTrigger.refresh());

        return () => {
          ScrollTrigger.getById(DEPLOYMENT_TRIGGER_ID)?.kill();
          timeline.kill();
          timelineRef.current = null;
          progress.value = 0;
          stageRef.current = 'dormant';
        };
      },
    );

    return () => {
      media.revert();
      ScrollTrigger.getById(DEPLOYMENT_TRIGGER_ID)?.kill();
      timelineRef.current?.kill();
      timelineRef.current = null;
    };
  }, { scope, dependencies: [sceneReady] });

  return timelineRef;
}
